import{_ as p,r as n,o,c,e as s,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"布局 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"使用动态页面标题","slug":"使用动态页面标题","link":"#使用动态页面标题","children":[]},{"level":2,"title":"占位符","slug":"占位符","link":"#占位符","children":[]},{"level":2,"title":"动态布局","slug":"动态布局","link":"#动态布局","children":[{"level":3,"title":"布局执行生命周期","slug":"布局执行生命周期","link":"#布局执行生命周期","children":[]}]}],"relativePath":"2.x/zh-cn/cms/layouts.md","filePath":"2.x/zh-cn/cms/layouts.md"}'),g={name:"2.x/zh-cn/cms/layouts.md"};function i(d,a,r,k,h,m){const t=n("pre-heading"),e=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"布局",-1)),s(e),a[1]||(a[1]=u(`<p>布局为您的页面定义了一个公用的框架，这通常意味着在每个页面上重复的所有内容，例如页眉和页脚。几乎所有页面都包含的 HTML 代码，例如 HEAD、TITLE 和 BODY 标签。</p><p>布局模板文件位于主题的 <strong>layouts</strong> 目录中。布局模板文件应具有 <strong>htm</strong> 扩展名。在布局文件中，您应该使用 <code>{% page %}</code> 标签来输出页面内容。接下来是最简单的布局示例。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>要为 <a href="./pages.html">页面</a> 使用布局，该页面应引用 <a href="./themes.html#oc-configuration-section">Configuration</a> 部分中的布局文件名(不带扩展名)。请记住，如果您从 <a href="./themes.html#oc-subdirectories">子目录</a> 引用布局，则应指定子目录名称。使用 default.htm 布局的示例页面模板：</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;/&quot;
layout = &quot;default&quot;
==
&lt;p&gt;Hello, world!&lt;/p&gt;
</code></pre></div><p>当这个页面被请求时，它的内容与布局合并，或者更准确地说 - 布局的 <code>{% page %}</code> 标签被页面内容替换。前面的示例将生成以下标记：</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Hello, world!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>请注意，您可以在布局中渲染 <a href="./partials.html">部件</a>。这使您可以在不同布局之间共享公共标记元素。例如，您可以有一个部件输出网站 CSS 和 JavaScript 链接。这种方法简化了资源管理 - 如果您想添加 JavaScript 引用，您应该修改单个部件而不是编辑所有布局。</p><p><a href="./themes.html#oc-configuration-section">Configuration</a> 部件对于布局是可选的。支持的配置参数是 <strong>name</strong> 和 <strong>description</strong>。这些参数是可选的，用于后端用户界面。带有描述的示例布局模板：</p><div class="language-twig extra-class"><pre class="language-twig"><code>description = &quot;基本布局示例&quot;
==
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">page</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="使用动态页面标题"><a href="#使用动态页面标题" class="header-anchor">#</a> 使用动态页面标题</h2><p><a href="./pages.html">页面</a> 的 <code>meta_title</code> 和 <code>meta_description</code> 属性支持从页面生命周期解析变量。以下布局模板将根据活动页面的值设置页面标题。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>title</span><span class="token punctuation">&gt;</span></span>{{ this.page.meta_title }} - October CMS<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>title</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
        {% page %}
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>然后页面模板可以使用类似于 Twig 的变量语法使用全局环境中可用的值定义其标题，在这种情况下使用 <strong>post.title</strong> 值。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>
<span class="token key attr-name">meta_title</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">{{ post.title }} - Blog</span>&quot;</span>
</code></pre></div><blockquote><p><strong>注意</strong>：仅支持基本的 Twig 变量。不能使用过滤器、标签和函数。</p></blockquote><p><a id="oc-placeholders"></a></p><h2 id="占位符"><a href="#占位符" class="header-anchor">#</a> 占位符</h2><p>占位符允许页面向布局注入内容。占位符在布局模板中使用 <code>{% placeholder %}</code> 标签定义。下一个示例显示了一个布局模板，其中在 HTML HEAD 中定义了一个占位符 <strong>head</strong>。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> head <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
    ...
</code></pre></div><p>页面可以使用 <code>{% put %}</code> 和 <code>{% endput %}</code> 标签向占位符注入内容。以下示例演示了一个简单的页面模板，该模板将 CSS 链接注入到上一个示例中定义的占位符 <strong>head</strong>。</p><div class="language- extra-class"><pre class="language-text"><code>url = &quot;/my-page&quot;
layout = &quot;default&quot;
==
{% put head %}
    &lt;link href=&quot;/themes/demo/assets/css/page.css&quot; rel=&quot;stylesheet&quot;&gt;
{% endput %}

&lt;p&gt;页面内容在这里&lt;/p&gt;
</code></pre></div><p>关于占位符的更多信息可以在 <a href="./../markup/tag-placeholder.html">标记指南</a> 中找到。</p><p><a id="oc-dynamic-layouts"></a></p><h2 id="动态布局"><a href="#动态布局" class="header-anchor">#</a> 动态布局</h2><p>布局，就像页面一样，可以使用任何 Twig 功能。详情请参考<a href="./pages.html#oc-dynamic-pages">动态页面</a> 文档。</p><h3 id="布局执行生命周期"><a href="#布局执行生命周期" class="header-anchor">#</a> 布局执行生命周期</h3><p>在布局的 <a href="./themes.html#oc-php-section">PHP 部分</a> 中，您可以定义以下用于处理页面执行生命周期的函数：<code>onInit</code>、<code>onStart</code>、<code>onBeforePageStart</code> 和 <code>onEnd</code>。</p><p><code>onInit</code> 函数在所有组件初始化时和 AJAX 请求被处理之前执行。 <code>onStart</code> 函数在页面处理开始时执行。 <code>onBeforePageStart</code> 函数在布局 <a href="./components.html">组件</a> 运行之后执行，但在页面的 <code>onStart</code> 函数执行之前。 <code>onEnd</code> 函数在页面呈现后执行。处理程序的执行顺序如下：</p><p>1.布局<code>onInit()</code>函数。 1.页面<code>onInit()</code>函数。 1.布局<code>onStart()</code>函数。 1.布局组件<code>onRun()</code>方法。 1.布局<code>onBeforePageStart()</code>函数。 1.页面<code>onStart()</code>函数。 1.页面组件<code>onRun()</code>方法。 1.页面<code>onEnd()</code>函数。 1.布局<code>onEnd()</code>函数。</p>`,30))])}const _=p(g,[["render",i]]);export{v as __pageData,_ as default};
